func main() {
    rand.Seed(time.Now().UnixNano())
    ticker := time.NewTicker(time.Second)
    done = make(chan bool); go worker()
    for {
        select {
            case <- done: println("done"); <- ticker.C
            case <- ticker.C: println("timeout"); return
        }
    }
}
